<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
class AemsProcessFlowDocument extends Model { use HasFactory; protected $fillable = ['planning_package_version_id','flow_code','title','description','process_owner_office_id','document_version_id','source_type','source_reference','sequence','audit_area_id','audit_focus_id','scope_statement','steps','inputs','outputs','records_systems','controls','decision_points','risk_points','limitations']; protected function casts(): array { return ['steps'=>'array','inputs'=>'array','outputs'=>'array','records_systems'=>'array','controls'=>'array','decision_points'=>'array','risk_points'=>'array','sequence'=>'integer']; } public function version(): BelongsTo { return $this->belongsTo(AemsPlanningPackageVersion::class,'planning_package_version_id'); } public function documentVersion(): BelongsTo { return $this->belongsTo(DocumentVersion::class); } public function processOwnerOffice(): BelongsTo { return $this->belongsTo(Office::class,'process_owner_office_id')->withTrashed(); } public function auditArea(): BelongsTo { return $this->belongsTo(AuditArea::class,'audit_area_id')->withTrashed(); } public function auditFocus(): BelongsTo { return $this->belongsTo(AuditFocus::class,'audit_focus_id')->withTrashed(); } }
